        hu: ["'Research Triangle Park' kutatási csomópont.", "Vezető szerep a gyógyszergyártásban.", "Központi szerep az orvosi kutatásokban.", "Magas koncentráció a biotechnológiai cégek területén."],
        ro: ["Centru de cercetare 'Research Triangle Park'.", "Lider în producția farmaceutică.", "Central pentru cercetarea medicală.", "Concentrație mare de companii biotehnologice."],
